N=$(mktemp -d) && printf 'import { expect, test } from "bun:test";
import { kindSmokeValue } from "%s/smoke/l200c-1";
test("negative control: wrong expected string", () => {
  expect(kindSmokeValue()).toBe("kind smoke l200c 2");
});
' "$LEGION_WORKSPACE" > "$N/neg.test.ts" && (cd "$N" && bun test neg.test.ts); echo "exit=$?"; rm -rf "$N"
